// Version A
function updateProfile(profile: { name: string; tags: string[] }, newTag: string) {
  return { ...profile, tags: [...profile.tags, newTag] };
}

// Version B
function updateProfileInPlace(profile: { name: string; tags: string[] }, newTag: string) {
  profile.tags.push(newTag);
  return profile;
}
